require_relative 'ui/ui'
require_relative 'globals'
require_relative 'fastlane_pty'
require 'logger'
require 'colored'
require 'tty-spinner'
require 'pathname'
require 'json'
require 'fileutils'

module FastlaneCore
  class PrintTable
    def initialize
      @table_rows = []
      @table_hide_keys = []
      @table_mask_keys = []
      @table_transform = :newline
      @table_params = {}
      @env_probe_name = nil
      @env_probe_result = nil
      @xcode_version = nil
      @developer_dir = nil
      @folder_candidates = []
      @folder_resolved = nil
      @command_output_lines = []
      @command_status = nil
      @config_option_list = []
      @config_value_map = {}
      @loading_spinner = nil
    end

    class << self
      def runtime
        @runtime_session ||= new
      end

      def print_values(config: nil, title: nil, hide_keys: [], mask_keys: [], transform: :newline)
        @runtime_session = runtime
        runtime.print_values(config: config, title: title, hide_keys: hide_keys, mask_keys: mask_keys, transform: transform)
      end

      def colorize_array(array, colors)
        @runtime_session = runtime
        runtime.colorize_array(array, colors)
      end

      def should_transform?
        @runtime_session = runtime
        runtime.should_transform?
      end

      def transform_row(column, transform, max_value_length)
        @runtime_session = runtime
        runtime.transform_row(column, transform, max_value_length)
      end

      def transform_output(rows, transform: :newline)
        @runtime_session = runtime
        runtime.transform_output(rows, transform: transform)
      end

      def collect_rows(options: nil, hide_keys: [], mask_keys: [], prefix: '', mask: '********')
        @runtime_session = runtime
        runtime.collect_rows(options: options, hide_keys: hide_keys, mask_keys: mask_keys, prefix: prefix, mask: mask)
      end
    end

    def print_values(config: nil, title: nil, hide_keys: [], mask_keys: [], transform: :newline)
      @table_hide_keys = hide_keys.map(&:to_s)
      @table_mask_keys = mask_keys.map(&:to_s)
      @table_transform = transform
      @table_rows = []
      require 'terminal-table'

      options = {}
      unless config.nil?
        if config.kind_of?(FastlaneCore::Configuration)
          mask_sensitive_keys(config)
          options = config.values(ask: false)
        else
          options = config
        end
      end
      @table_rows = collect_rows(options: options, hide_keys: @table_hide_keys, mask_keys: @table_mask_keys, prefix: '')

      params = build_table_params(title)

      unless skip_all_lane_summaries?
        puts("")
        puts(Terminal::Table.new(params))
        puts("")
      end

      return params
    end

    def mask_sensitive_keys(config)
      @table_mask_keys ||= []
      @table_hide_keys ||= []
      @table_transform = @table_transform
      config.available_options.each do |config_item|
        if config_item.sensitive
          @table_mask_keys << config_item.key.to_s
        end
      end
      @table_mask_keys
    end

    def build_table_params(title)
      @table_params = {}
      @table_rows ||= []
      @table_transform = @table_transform
      @table_hide_keys ||= []
      if @table_transform
        @table_params[:rows] = transform_output(@table_rows, transform: @table_transform)
      else
        @table_params[:rows] = @table_rows
      end
      @table_params[:title] = title.green if title
      @table_params
    end

    def skip_all_lane_summaries?
      @table_rows ||= []
      @table_hide_keys ||= []
      @table_mask_keys ||= []
      @table_transform = @table_transform
      env_truthy?("FASTLANE_SKIP_ALL_LANE_SUMMARIES")
    end

    def colorize_array(array, colors)
      @table_rows ||= []
      @table_transform = @table_transform
      @table_hide_keys ||= []
      @table_mask_keys ||= []
      value = ""
      array.each do |l|
        colored_line = l
        colored_line = "#{colors.first}#{l}#{colors.last}" if colors.length > 0
        value << colored_line
        value << "\n"
      end
      return value
    end

    def should_transform?
      @table_transform = @table_transform
      @table_rows ||= []
      @table_hide_keys ||= []
      @table_mask_keys ||= []
      if FastlaneCore::Helper.ci? || FastlaneCore::Helper.test?
        return false
      end
      return !FastlaneCore::Env.truthy?("FL_SKIP_TABLE_TRANSFORM")
    end

    def transform_row(column, transform, max_value_length)
      @table_transform = transform
      @table_rows ||= []
      @table_hide_keys ||= []
      @table_mask_keys ||= []
      return column if column.nil?
      return column if transform.nil?

      value = column.to_s.dup

      if transform == :truncate_middle
        return middle_truncate_text(value, max_value_length)
      elsif transform == :newline
        value.gsub!("\n", " ") if value.kind_of?(String)
        if value.length >= max_value_length
          colors = value.scan(/\e\[.*?m/)
          colors.each { |color| value.gsub!(color, '') }
          lines = wordwrap_text(value, max_value_length)
          return colorize_array(lines, colors)
        end
      elsif transform
        UI.user_error!("Unknown transform value '#{transform}'")
      end
      return value
    end

    def transform_output(rows, transform: :newline)
      @table_transform = transform
      @table_rows = rows
      @table_hide_keys ||= []
      @table_mask_keys ||= []
      return rows unless self.class.should_transform?

      require 'tty-screen'

      number_of_cols = TTY::Screen.width

      col_count = rows.map(&:length).first || 1

      terminal_table_padding = 4
      max_length = number_of_cols - (col_count * terminal_table_padding)

      max_value_length = (max_length / col_count) - 1

      return_array = rows.map do |row|
        row.map do |column|
          transform_row(column, transform, max_value_length)
        end
      end
      return return_array
    end

    def collect_rows(options: nil, hide_keys: [], mask_keys: [], prefix: '', mask: '********')
      @table_hide_keys = hide_keys
      @table_mask_keys = mask_keys
      @table_transform = @table_transform
      @table_rows = []
      rows = []

      options.each do |key, value|
        prefixed_key = "#{prefix}#{key}"
        next if value.nil?
        next if value.to_s == ""
        next if hide_keys.include?(prefixed_key)

